from itertools import product

# Generate all possible binary sequences of length 13
sequences = list(product([-1, 1], repeat=13))

# Filter sequences that sum up to 1
valid_sequences = [seq for seq in sequences if sum(seq) == 1]

# Check for Legendre pairs
for x in valid_sequences:
    for y in valid_sequences:
        if all(sum(x[i] * x[(i+k) % 13] for i in range(13)) + sum(y[i] * y[(i+k) % 13] for i in range(13)) == -2 for k in range(1, 7)):
            print([int(i) for i in x + y])
            break
    else:
        continue
    break
else:
    print("UNSATISFIABLE")
